function metrics(){const opp=S.ghl.opportunities,total=opp.reduce((a,o)=>a+Number(o.monetaryValue||0),0),deliveries=todayDelivery(),ready=deliveries.filter(j=>(j.notes||j.scope||j.walkthroughNotes)&&Number(j.priceQuoted||j.total||0)).length,reset=S.ghl.leadResetAt?new Date(S.ghl.leadResetAt).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'America/Denver'}):'the reset',billable=jobs().filter(j=>j.type==='job'),openBalance=billable.reduce((sum,j)=>sum+financeState(j).balance,0),overdue=billable.filter(j=>financeState(j).invoice==='overdue').reduce((sum,j)=>sum+financeState(j).balance,0);return`<div class="ops-metrics"><article><span>New HighLevel leads</span><strong>${S.ghl.error?'—':opp.length}</strong><small>${S.ghl.error?'Connect CRM when the key is ready':`${money(total)} open value · since ${reset}`}</small></article><article><span>Walkthroughs today</span><strong>${todayWalkthroughs().length}</strong><small>Scheduled in the EGC Hub</small></article><article><span>Jobs today</span><strong>${deliveries.length}</strong><small>${ready} handoff-ready · ${deliveries.length-ready} need attention</small></article><article class="accent"><span>Cash outstanding</span><strong>${money(openBalance)}</strong><small>${overdue?`${money(overdue)} overdue`:'No overdue invoices'}</small></article></div>`}
function flywheel(){const rows=[['01','Lead response','HIGHLEVEL','Respond fast; sell the free walkthrough.'],['02','Walkthrough','FIELD','Diagnose pain, design outcome, lock scope and price.'],['03','Crew handoff','EGC HUB','Carry every promise, hazard, keep item and photo forward.'],['04','Reveal','FIELD','Final walkthrough, surprise gift, collect, ask for review.'],['05','Proof loop','GROWTH','Publish the transformation and feed the winning hook.']];return`<section class="ops-card ops-fly"><div class="ops-card-head"><div><span class="ops-eyebrow">THE OPERATING LOOP</span><h2>One promise, carried all the way through</h2></div>${badge('Walkthrough-first','info')}</div><div class="ops-fly-row">${rows.map(r=>`<article><b>${r[0]}</b><span>${r[2]}</span><h3>${r[1]}</h3><p>${r[3]}</p></article>`).join('')}</div></section>`}
function agenda(){const rows=todayJobs().map(x=>({...x,kind:x.type==='walkthrough'?'Walkthrough':'Job',at:x.date+'T'+(x.time||'08:00')})).sort((a,b)=>String(a.at).localeCompare(String(b.at)));if(!rows.length)return empty('Nothing scheduled today','Add a walkthrough, job, or blocked time in the Hub schedule.',`<button class="ops-button primary" onclick="opsOpenBooking()">Schedule work</button>`);return`<div class="ops-agenda">${rows.map(r=>`<article><time>${timeLabel(r.at)||'TBD'}</time><div><span>${r.kind} · ${esc(jobStage(r).replaceAll('_',' '))}</span><strong>${esc(r.customer||r.title||'Customer')}</strong><p>${esc(r.address||'Address not recorded')}</p></div><div class="ops-agenda-actions">${r.address?`<a href="${routeUrl(r.address)}" target="_blank" rel="noopener">Route</a>`:''}<a href="${r.kind==='Walkthrough'?`/crew/gameplan.html?walkthroughId=${encodeURIComponent(r.id)}`:`/crew/prejob.html?jobId=${encodeURIComponent(r.id)}`}">${r.kind==='Walkthrough'?'Start walkthrough':'Open crew brief'} →</a></div></article>`).join('')}</div>`}
function attention(){const x=[];if(S.ghl.error==='not-configured')x.push(['HighLevel is not connected','Add the API key and location ID in Cloudflare.','settings']);const pendingAccounts=(S.people.accounts||[]).filter(a=>a.status==='pending').length,pendingTime=(S.people.timeEntries||[]).filter(t=>t.approvalStatus==='pending'||t.status==='submitted').length,pendingRequests=(S.people.requests||[]).filter(r=>r.status==='pending').length;if(pendingAccounts)x.push([`${pendingAccounts} employee account${pendingAccounts===1?'':'s'} waiting`,'Approve or reject access before the employee can sign in.','people']);if(pendingTime)x.push([`${pendingTime} timecard${pendingTime===1?'':'s'} awaiting approval`,'Review completed shifts before the Gusto export.','timesheets']);if(pendingRequests)x.push([`${pendingRequests} employee request${pendingRequests===1?'':'s'} open`,'Review time off and schedule requests.','people']);jobs().filter(j=>financeState(j).invoice==='overdue').slice(0,3).forEach(j=>x.push([`${j.customer||'Customer'} has ${money(financeState(j).balance)} overdue`,`Invoice ${j.invoice?.number||''} was due ${j.invoice?.dueDate||'earlier'}.`,'finance']));jobs().filter(j=>(j.rebookingRequests||[]).some(r=>r.status==='pending')).slice(0,3).forEach(j=>x.push([`${j.customer||'Customer'} wants to rebook`,'Review their service, timing, and preferred-crew request.','customers']));jobs().filter(j=>(j.customerDecisions||[]).some(d=>d.status==='pending')).slice(0,3).forEach(j=>x.push([`${j.customer||'Customer'} has a decision waiting`,'The crew cannot assume an answer; follow up through the private portal.','delivery']));jobs().filter(j=>(j.giftWallet?.transferRequests||[]).some(t=>t.status==='pending')).slice(0,2).forEach(j=>x.push([`${j.customer||'Customer'} requested a gift-card transfer`,'Verify the recipient before moving customer credit.','customers']));jobs().filter(j=>j.communicationLastStatus==='needs_attention').slice(0,3).forEach(j=>x.push([`${j.customer||'Customer'} message needs retry`,'The Hub kept the HighLevel trigger and audit record.','communications']));jobs().filter(j=>j.closeoutSyncStatus==='error').slice(0,3).forEach(j=>x.push([`${j.customer||'Job'} closeout needs HighLevel retry`,'The full closeout is safe in the Hub. Retry it from customer history.','customers']));jobs().filter(j=>Number(j.photoCount||j.jobInstructions?.photoCount||0)>0&&!j.photoDriveUrl&&['device_only','needs_setup','error'].includes(j.photoSyncStatus)).slice(0,2).forEach(j=>x.push([`${j.customer||'Job'} photos are not in Drive`,j.photoSyncStatus==='needs_setup'?'Connect Google Drive, then reopen and save the walkthrough on the original device.':'Reopen and save the walkthrough on the original device to retry the upload.','delivery']));openJobs().slice(0,5).forEach(j=>{const crew=crewNames(j),needed=Math.max(1,Number(j.crewNeeded||1));if(!j.notes&&!j.scope&&!j.walkthroughNotes)x.push([`${j.customer||'Job'} has no crew brief`,'Carry the walkthrough promise into delivery.','delivery']);else if(!Number(j.priceQuoted||j.total||0))x.push([`${j.customer||'Job'} has no locked total`,'Confirm the flat rate before the crew rolls.','delivery']);else if(String(j.date||'')<=financeDatePlus(1)&&crew.length<needed)x.push([`${j.customer||'Job'} needs ${needed-crew.length} more crew`,'Fill the shift before tomorrow’s route.','schedule'])});if(!x.length)x.push(['The operating queue is clean','No overdue cash, access approvals, timecards, sync failures, or incomplete handoffs.','walkthroughs']);return`<div class="ops-attention">${x.slice(0,10).map(i=>`<button onclick="opsGo('${i[2]}')"><i></i><div><strong>${esc(i[0])}</strong><small>${esc(i[1])}</small></div><b>→</b></button>`).join('')}</div>`}

const isoDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function weekStart(value=S.weekAnchor){const d=value?new Date(value+'T12:00:00'):new Date(),shift=(d.getDay()+6)%7;d.setDate(d.getDate()-shift);d.setHours(12,0,0,0);return d}
function weekDays(){const start=weekStart();return Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return isoDate(d)})}
function availabilityMonth(){const source=S.availabilityAnchor||day().slice(0,7)+'-01',date=new Date(source+'T12:00:00');date.setDate(1);return date}
function availabilityCalendar(identity){const month=availabilityMonth(),first=new Date(month),lead=(first.getDay()+6)%7;first.setDate(first.getDate()-lead);const selected=S.availabilitySelected||day(),blocks=activeAvailability().filter(x=>sameEmployee(x.employee,identity)),days=Array.from({length:42},(_,index)=>{const date=new Date(first);date.setDate(first.getDate()+index);const key=isoDate(date),monthDay=date.getMonth()===month.getMonth(),blocked=blocks.filter(x=>x.date===key),classes=[monthDay?'':'outside',key===day()?'today':'',key===selected?'selected':'',blocked.length?'blocked':''].filter(Boolean).join(' '),detail=blocked.map(x=>x.allDay?'All day':`${eventTime(x)}–${x.endTime}`).join(', ');return`<button type="button" class="${classes}" onclick="opsSelectAvailabilityDay('${key}')" aria-label="${esc(dateLabel(key+'T12:00:00'))}${detail?' · unavailable '+esc(detail):''}"><span>${date.getDate()}</span>${blocked.length?`<b>${blocked.some(x=>x.allDay)?'Off':'Busy'}</b>`:'<i></i>'}</button>`});return`<div class="ops-timeoff-calendar"><header><button type="button" onclick="opsAvailabilityMove(-1)" aria-label="Previous month">←</button><strong>${month.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</strong><button type="button" onclick="opsAvailabilityMove(1)" aria-label="Next month">→</button></header><div class="ops-calendar-weekdays">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<span>${x}</span>`).join('')}</div><div class="ops-calendar-days">${days.join('')}</div><footer><span><i></i> Available</span><span><i class="blocked"></i> Time blocked</span><button type="button" onclick="opsAvailabilityToday()">Jump to today</button></footer></div>`}
function eventTime(j){return j.time||String(j.startTime||'').slice(11,16)||'TBD'}
function syncState(j){if(j.type==='blocked')return badge('Hub only','info');const lifecycle=j.lifecycleSync?.status==='error'?`${badge('Workflow sync failed','warn')}<button class="ops-retry" type="button" onclick="event.stopPropagation();opsRetryLifecycle('${esc(j.id)}')">Retry</button>`:'';if(j.syncStatus==='synced')return badge('Synced','good')+lifecycle;if(j.syncStatus==='syncing')return badge('Syncing','info')+lifecycle;return `${badge(j.syncStatus==='error'?'Sync failed':'Sync pending',j.syncStatus==='error'?'warn':'info')}<button class="ops-retry" type="button" onclick="event.stopPropagation();opsRetrySync('${esc(j.id)}')">Retry</button>${lifecycle}`}
function photoState(j){const count=Number(j.proofPhotoCount||j.photoCount||j.jobInstructions?.photoCount||0);if(!count)return'';const url=String(j.photoDriveUrl||''),safe=/^https:\/\/(?:drive|docs)\.google\.com\//i.test(url),linked=(text,tone)=>`<a class="ops-photo-link" href="${esc(url)}" target="_blank" rel="noopener" onclick="event.stopPropagation()">${badge(text,tone)}</a>`;if(safe&&['error','partial'].includes(j.photoSyncStatus))return linked(`${count} photos · upload incomplete`,'warn');if(safe)return linked(`${count} photo${count===1?'':'s'} in Drive`,'good');if(j.photoSyncStatus==='needs_setup')return badge(`${count} photos · Drive setup needed`,'warn');if(['error','partial'].includes(j.photoSyncStatus))return badge(`${count} photos · upload incomplete`,'warn');return badge(`${count} photos · original device`,'info')}
function scheduleGrid(){return`<div class="ops-week">${weekDays().map(date=>{const rows=jobs().filter(j=>String(j.date||j.startTime||'').slice(0,10)===date&&!['cancelled'].includes(jobStage(j))).sort((a,b)=>eventTime(a).localeCompare(eventTime(b)));const d=new Date(date+'T12:00:00');return`<section class="${date===day()?'today':''}"><header><span>${d.toLocaleDateString('en-US',{weekday:'short'})}</span><strong>${d.getDate()}</strong><button type="button" onclick="opsOpenBooking('${date}')" aria-label="Schedule on ${date}">+</button></header><div>${rows.length?rows.map(j=>`<article class="${esc(j.type||'job')}"><time>${esc(eventTime(j))}–${esc(j.endTime||'')}</time><strong>${esc(j.customer||j.title||j.serviceType||'Blocked time')}</strong><small>${esc(j.address||j.assignedTo||'')}</small><footer><span>${esc(j.type==='walkthrough'?'Walkthrough':j.type==='blocked'?'Blocked':j.recurrence&&j.recurrence!=='none'?'Recurring job':'Job')}</span>${activeScheduleJob(j)?`<button class="ops-edit-event" type="button" onclick="opsEditBooking('${esc(j.id)}')">Edit</button>`:`<b>${esc(jobStage(j).replaceAll('_',' '))}</b>`}${syncState(j)}</footer></article>`).join(''):`<button class="ops-day-empty" type="button" onclick="opsOpenBooking('${date}')">Add time</button>`}</div></section>`}).join('')}</div>`}
function bookingModal(){if(!S.booking)return'';const b=S.booking,results=S.contactResults||[];return`<div class="ops-modal" role="dialog" aria-modal="true" aria-label="Schedule work"><button class="ops-modal-scrim" type="button" onclick="opsCloseBooking()" aria-label="Close"></button><form class="ops-booking" onsubmit="opsSaveBooking(event)"><header><div><span class="ops-eyebrow">EGC HUB SCHEDULE</span><h2>${b.id?'Edit scheduled time':'Add scheduled time'}</h2><p>Saved here first, collision-checked, then synchronized to HighLevel.</p></div><button type="button" onclick="opsCloseBooking()">×</button></header><div class="ops-form-grid"><label><span>Type</span><select name="type" onchange="opsBookField('type',this.value)" ${b.id?'disabled title="Event type locks after the first save"':''}><option value="walkthrough" ${b.type==='walkthrough'?'selected':''}>Free walkthrough</option><option value="job" ${b.type==='job'?'selected':''}>Customer job</option><option value="blocked" ${b.type==='blocked'?'selected':''}>Blocked time</option></select></label><label><span>Customer / label</span><input name="customer" required value="${esc(b.customer)}" oninput="opsBookField('customer',this.value)" placeholder="Customer name"></label><label class="wide"><span>Find CRM contact</span><div class="ops-contact-find"><input type="search" placeholder="Name, phone, or email" oninput="opsLookupContacts(this.value)"><em>HighLevel</em></div>${results.length?`<div class="ops-contact-results">${results.map((c,i)=>`<button type="button" onclick="opsPickContact(${i})"><b>${esc(c.name)}</b><span>${esc(c.phone||c.email||c.address)}</span></button>`).join('')}</div>`:''}</label><label><span>Mobile</span><input name="phone" value="${esc(b.phone)}" oninput="opsBookField('phone',this.value)" placeholder="(970) 555-0123"></label><label><span>Email</span><input name="email" type="email" value="${esc(b.email)}" oninput="opsBookField('email',this.value)" placeholder="name@email.com"></label><label class="wide"><span>Address</span><input name="address" value="${esc(b.address)}" oninput="opsBookField('address',this.value)" placeholder="Service address"></label><label><span>Date</span><input name="date" type="date" required value="${esc(b.date)}" onchange="opsBookField('date',this.value)"></label><label><span>Start</span><input name="time" type="time" required value="${esc(b.time)}" onchange="opsBookField('time',this.value)"></label><label><span>End</span><input name="endTime" type="time" required value="${esc(b.endTime)}" onchange="opsBookField('endTime',this.value)"></label><label><span>Assigned crew</span><input name="assignedTo" value="${esc(b.assignedTo)}" oninput="opsBookField('assignedTo',this.value)" placeholder="Zac + Tyler"></label><label><span>Crew needed</span><input name="crewNeeded" type="number" min="1" max="12" required value="${esc(b.crewNeeded||2)}" oninput="opsBookField('crewNeeded',this.value)"></label><label><span>Visit cadence</span><select name="recurrence" onchange="opsBookField('recurrence',this.value)"><option value="none">One-time visit</option>${[['weekly','Weekly'],['biweekly','Every 2 weeks'],['monthly','Monthly'],['quarterly','Every 3 months']].map(x=>`<option value="${x[0]}" ${b.recurrence===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></label><label><span>Reminder lead time</span><select name="reminderDays" onchange="opsBookField('reminderDays',this.value)">${[['1','1 day'],['2','2 days'],['3','3 days'],['7','1 week']].map(x=>`<option value="${x[0]}" ${String(b.reminderDays)===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></label><label class="wide"><span>Internal notes</span><textarea name="notes" oninput="opsBookField('notes',this.value)" placeholder="Access, expectations, crew notes…">${esc(b.notes)}</textarea></label><label class="wide ops-notify ops-open-shift ${b.type==='job'?'':'ops-hidden'}"><input name="openShift" type="checkbox" ${b.openShift?'checked':''} onchange="opsBookField('openShift',this.checked)"><span><b>Manager: open remaining crew spots for pickup</b><small>Employees can claim until Crew needed is reached.</small></span></label><label class="wide ops-notify ${b.type==='blocked'?'ops-hidden':''}"><input name="notify" type="checkbox" ${b.notify?'checked':''} onchange="opsBookField('notify',this.checked)"><span>Let HighLevel send confirmation and reminder workflows</span></label></div><footer><span id="ops-booking-status">Hub is the schedule of record.</span><div>${b.id?`<button type="button" class="ops-button danger" onclick="opsCancelBooking('${esc(b.id)}')">Cancel appointment</button>`:''}<button type="button" class="ops-button" onclick="opsCloseBooking()">Close</button><button class="ops-button primary">${b.id?'Update + sync':'Save + sync'}</button></div></footer></form></div>`}
function openBooking(date=day()){S.booking={type:'walkthrough',customer:'',phone:'',email:'',address:'',date,time:'09:00',endTime:'10:00',assignedTo:'',assignedCrew:[],crewNeeded:2,openShift:false,notes:'',notify:true,recurrence:'none',reminderDays:'2',highlevelContactId:''};S.contactResults=[];render()}
