let contactTimer;window.opsLookupContacts=q=>{clearTimeout(contactTimer);contactTimer=setTimeout(async()=>{if(!S.booking||String(q).trim().length<2){S.contactResults=[];return}try{const r=await hubFetch('/api/highlevel?view=contacts&q='+encodeURIComponent(String(q).trim())),j=await r.json();S.contactResults=r.ok?j.contacts||[]:[];render()}catch{S.contactResults=[]}},350)};
window.opsPickContact=i=>{const c=S.contactResults[i];if(!c||!S.booking)return;Object.assign(S.booking,{customer:c.name||S.booking.customer,phone:c.phone||'',email:c.email||'',address:c.address||'',highlevelContactId:c.id||''});S.contactResults=[];render()};
window.opsWeekMove=n=>{const d=weekStart();d.setDate(d.getDate()+Number(n)*7);S.weekAnchor=isoDate(d);render()};window.opsWeekToday=()=>{S.weekAnchor='';render()};
