function replaceBriefLine(brief,label,value){if(!brief)return'';const lines=String(brief).split('\n'),next=`${label}: ${value}`,index=lines.findIndex(line=>line.startsWith(label+':'));if(index>=0)lines[index]=next;else lines.push(next);return lines.join('\n').slice(0,4900)}
