function refreshWalkthroughHandoff(previous,b,assignedCrew,crewNeeded){if(!previous.internalNotes)return{};const assignedTo=assignedCrew.join(' + ')||b.assignedTo||'',arrivalWindow=`${b.date} · ${b.time}–${b.endTime}`,customerNotes=b.notes||'',jobInstructions={...(previous.jobInstructions||{}),customerNotes,assignedTo,crewSize:crewNeeded,arrivalWindow},internalNotes=replaceBriefLine(replaceBriefLine(previous.internalNotes,'CREW / WINDOW',[assignedTo,`${crewNeeded} crew`,arrivalWindow].filter(Boolean).join(' · ')),'INTERNAL CUSTOMER NOTES',customerNotes||'None recorded'),clientChecklists=refreshChecklistNotes(previous.clientChecklists,customerNotes),logistics={...(previous.logistics||{}),assigned_to:assignedTo,crew_size:crewNeeded};return{jobInstructions,internalNotes,clientChecklists,logistics,customerNotesSummary:customerNotes||previous.customerNotesSummary||jobInstructions.customerGoal||''}}
