const customerCommunicationTypes={
  'estimate-ready':{label:'Estimate ready',description:'Tells the customer their flat-rate estimate is ready to review.'},
  'estimate-approved':{label:'Estimate approved',description:'Confirms the approval and next scheduling step.'},
  'estimate-expiring':{label:'Estimate expiring',description:'One reminder the day before the approval deadline.'},
  'invoice-issued':{label:'Invoice issued',description:'Notifies the customer that their balance and due date are ready.'},
  'invoice-overdue':{label:'Invoice overdue',description:'One respectful reminder after the due date passes.'},
  'deposit-received':{label:'Deposit received',description:'Confirms the deposit was recorded.'},
  'payment-received':{label:'Payment received',description:'Confirms payment and points to the receipt.'},
  'appointment-reminder':{label:'Appointment reminder',description:'Sends the current appointment details again.'},
  'review-requested':{label:'Review request',description:'Starts the HighLevel review workflow after a completed job.'},
  'decision-needed':{label:'Decision needed',description:'Tells an unavailable customer that the crew needs an approval in their private portal.'},
  'rebooking-received':{label:'Rebooking received',description:'Confirms that the team received a portal rebooking request.'},
};
function communicationNote(job,event){const type=customerCommunicationTypes[event],f=financeState(job),parts=[type?.label||event,job.estimate?.number||job.invoice?.number||'',job.date?`Service date ${job.date}`:'',event.startsWith('invoice')?`Balance ${payMoney(f.balance)}`:'',event.startsWith('estimate')?`Estimate ${payMoney(f.total)}`:''];return parts.filter(Boolean).join(' · ')}
async function syncCustomerCommunication(job,event,marker='manual'){if(!job||!customerCommunicationTypes[event])return false;const attemptedAt=new Date().toISOString(),key=`communication:${job.id}:${event}:${marker}`,payload={tool:'lifecycle',event,idempotency_key:key,highlevel_contact_id:job.highlevelContactId||'',appointment_id:job.highlevelAppointmentId||'',suppress_automation:job.notify===false,note:communicationNote(job,event),client:{name:job.customer||'',phone:job.phone||'',email:job.email||'',address:job.address||'',highlevel_contact_id:job.highlevelContactId||''}},sent=await syncLifecycle(job,event,payload),current=jobs().find(x=>x.id===job.id)||job,prior=Array.isArray(current.communicationLog)?current.communicationLog:[],status=job.notify===false?'suppressed':sent?'triggered':'needs_attention',entry={id:key,event,label:customerCommunicationTypes[event].label,status,source:marker==='manual'?'manager':'automatic',attemptedAt,trigger:sent&&job.notify!==false?`egc-${event}`:''},communicationLog=[...prior.filter(item=>item.id!==key),entry].slice(-40),update={communicationLog,communicationLastEvent:event,communicationLastStatus:status,communicationLastAt:attemptedAt,updatedAt:attemptedAt};if(sent&&marker!=='manual')update.automationMilestones={...(current.automationMilestones||{}),[event]:marker};await patchJob(job.id,update);return sent}
window.opsTriggerCommunication=async(id,event)=>{const job=jobs().find(x=>x.id===id),type=customerCommunicationTypes[event];if(!job||!type)return;const approval=await askAction({kicker:'CUSTOMER COMMUNICATION',title:`Trigger “${type.label}” for ${job.customer||'this customer'}?`,copy:`${type.description} HighLevel owns delivery, consent, opt-outs, and conversation history.`,confirmLabel:'Trigger in HighLevel',fields:[],note:`Automation tag: egc-${event}`});if(!approval)return;const sent=await syncCustomerCommunication(job,event,'manual');render();if(typeof showToast==='function')showToast(sent?'HighLevel automation triggered':'Saved for retry · HighLevel needs attention')};
window.opsSetCustomerAutomation=async(id,enabled)=>{const job=jobs().find(x=>x.id===id);if(!job)return;if(enabled){const approval=await askAction({kicker:'AUTOMATIC REMINDERS',title:`Enable automatic reminders for ${job.customer||'this customer'}?`,copy:'The Hub will trigger one estimate-expiring reminder and one invoice-overdue reminder through HighLevel. HighLevel still enforces consent and opt-outs.',confirmLabel:'Enable reminders',fields:[],note:'Existing overdue items are eligible on the next manager refresh.'});if(!approval)return}await patchJob(id,{customerAutomationEnabled:Boolean(enabled),customerAutomationUpdatedAt:new Date().toISOString(),customerAutomationUpdatedBy:employeeIdentity(),updatedAt:new Date().toISOString()});render();if(typeof showToast==='function')showToast(enabled?'Automatic reminders enabled':'Automatic reminders paused')};
function communicationActions(j){const f=financeState(j),items=[];if(j.estimate?.number)items.push(['estimate-ready','Estimate ready']);if(j.invoice?.number&&f.balance>0)items.push([f.invoice==='overdue'?'invoice-overdue':'invoice-issued',f.invoice==='overdue'?'Overdue reminder':'Invoice due']);if(f.paid>0)items.push(['payment-received','Payment receipt']);if(['completed','invoiced','paid','review_requested','closed'].includes(jobStage(j)))items.push(['review-requested','Review request']);if(String(j.date||'')>=day())items.push(['appointment-reminder','Appointment reminder']);return items.map(item=>`<button type="button" onclick="opsTriggerCommunication('${esc(j.id)}','${item[0]}')">${item[1]}</button>`).join('')+`<button type="button" onclick="opsSetCustomerAutomation('${esc(j.id)}',${j.customerAutomationEnabled!==true})">${j.customerAutomationEnabled===true?'Pause auto':'Enable auto'}</button>`}
function communicationBoard(){const rows=jobs().filter(j=>j.type==='job'&&(j.phone||j.email)).sort((a,b)=>String(b.updatedAt||b.date||'').localeCompare(String(a.updatedAt||a.date||'')));if(!rows.length)return empty('No customer communication records yet','Jobs with a phone number or email appear here after they are saved in the Hub.');return`<div class="ops-job-list">${rows.map(j=>{const log=Array.isArray(j.communicationLog)?j.communicationLog:[],last=log.at(-1),f=financeState(j);return`<article><div><span class="ops-readiness ${last?.status==='needs_attention'?'warn':'ready'}">${esc(last?last.status.replaceAll('_',' '):'ready')}</span><h3>${esc(j.customer||'Customer')}</h3><p>${esc(j.phone||j.email)} · ${esc(j.serviceType||'Garage service')}</p><p>${last?`${esc(last.label)} · ${dateLabel(last.attemptedAt)} ${timeLabel(last.attemptedAt)}`:'No Hub-triggered message yet'}</p></div><div class="ops-job-price"><strong>${money(f.balance)}</strong><span>open balance</span>${badge(j.notify===false?'Automation suppressed':'HighLevel owns delivery',j.notify===false?'warn':'info')}</div><div class="ops-job-actions">${communicationActions(j)}</div></article>`}).join('')}</div>`}
async function runCustomerCommunicationMilestones(){const tomorrow=financeDatePlus(1),candidates=[];for(const job of jobs()){if(job.type!=='job'||job.customerAutomationEnabled!==true||job.notify===false||(!job.phone&&!job.email))continue;const f=financeState(job),approved=['approved','accepted'].includes(String(job.estimate?.status||'').toLowerCase());if(job.estimate?.validUntil===tomorrow&&!approved&&job.automationMilestones?.['estimate-expiring']!==job.estimate.validUntil)candidates.push([job,'estimate-expiring',job.estimate.validUntil]);if(f.invoice==='overdue'&&job.automationMilestones?.['invoice-overdue']!==f.dueDate)candidates.push([job,'invoice-overdue',f.dueDate])}for(const [job,event,marker] of candidates.slice(0,3))await syncCustomerCommunication(job,event,marker)}
function financeDatePlus(days,from=day()){const value=new Date(`${from}T12:00:00`);value.setDate(value.getDate()+Number(days||0));return isoDate(value)}
function financeState(j){const invoiceActive=j.invoice?.amount&&!['draft','superseded','void'].includes(j.invoice?.status),total=Number(invoiceActive?j.invoice.amount:j.estimate?.amount||j.total||j.priceQuoted||0),paid=Number(j.payment?.amount||0),deposit=Number(j.deposit?.amount||0),balance=Math.max(0,total-paid),dueDate=j.invoice?.dueDate||'',invoiceBase=j.invoice?.status||'not issued',invoice=balance>0&&dueDate&&dueDate<day()&&!['paid','void','superseded'].includes(invoiceBase)?'overdue':invoiceBase;return{total,paid,deposit,balance,estimate:j.estimate?.status||'not created',invoice,dueDate,validUntil:j.estimate?.validUntil||''}}
function jobEconomics(j){const f=financeState(j),hours=Number(j.hoursOnSite||j.timeTracking?.elapsedHours||0),crew=Math.max(1,Number(j.crewSize||j.crewNeeded||crewNames(j).length||1)),crewHours=hours*crew,costs=j.costs||{},labor=Number(costs.labor??j.laborCost??(crewHours?crewHours*20:0)),disposal=Number(costs.disposal??j.dumpFees??0),materials=Number(costs.materials||0),fuel=Number(costs.fuel||0),processing=Number(costs.processing||0),other=Number(costs.other||0),directCost=labor+disposal+materials+fuel+processing+other,known=Boolean(costs.recordedAt)||hours>0,contribution=known?f.total-directCost:0,margin=known&&f.total?contribution/f.total*100:0,revenuePerCrewHour=crewHours?f.total/crewHours:0,loadVariance=Number(j.scopeVariance?.difference||0);return{...f,hours,crew,crewHours,labor,disposal,materials,fuel,processing,other,directCost,known,contribution,margin,revenuePerCrewHour,loadVariance}}
function financeSummary(){const rows=jobs().filter(j=>j.type!=='walkthrough'&&j.type!=='blocked'&&jobStage(j)!=='cancelled'),sold=rows.reduce((n,j)=>n+financeState(j).total,0),collected=rows.reduce((n,j)=>n+financeState(j).paid,0),known=rows.map(jobEconomics).filter(x=>x.known),contribution=known.reduce((n,x)=>n+x.contribution,0);return`<div class="ops-metrics"><article><span>Sold work</span><strong>${money(sold)}</strong><small>${rows.length} billable job${rows.length===1?'':'s'}</small></article><article><span>Collected</span><strong>${money(collected)}</strong><small>${sold?Math.round(collected/sold*100):0}% of sold work</small></article><article><span>Open balance</span><strong>${money(Math.max(0,sold-collected))}</strong><small>Hub records, before accounting sync</small></article><article class="accent"><span>Known job contribution</span><strong>${money(contribution)}</strong><small>${known.length} costed job${known.length===1?'':'s'} · before overhead and ads</small></article></div>`}
function financeBoard(){const rows=jobs().filter(j=>j.type!=='walkthrough'&&j.type!=='blocked'&&jobStage(j)!=='cancelled').sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));if(!rows.length)return empty('No billable jobs yet','Complete a walkthrough or schedule a customer job to start an estimate.');return`<div class="ops-finance-list">${rows.map(j=>{const f=financeState(j),e=jobEconomics(j);return`<article><div><span>${esc(j.invoice?.number||j.estimate?.number||'UNBILLED')}</span><h3>${esc(j.customer||'Customer')}</h3><p>${dateLabel((j.date||'')+'T12:00:00')} · ${esc(j.serviceType||'Garage service')}</p></div><div><b>${money(f.total)}</b><small>${money(f.balance)} balance · ${money(f.deposit)} deposit recorded</small>${e.known?`<small>${e.crewHours.toFixed(1)} crew-hrs · ${money(e.directCost)} direct cost</small><small>${money(e.contribution)} contribution · ${e.margin.toFixed(1)}% margin · ${money(e.revenuePerCrewHour)}/crew-hr</small>`:''}</div><div class="ops-finance-state">${badge('Estimate: '+f.estimate,f.estimate==='accepted'?'good':'info')}${badge('Invoice: '+f.invoice,f.invoice==='paid'?'good':'')}${e.known?badge(`Costs ${j.costs?.recordedAt?'actual':'baseline'}`,j.costs?.recordedAt?'good':'info'):''}${e.loadVariance?badge(`Load variance ${e.loadVariance>0?'+':''}${e.loadVariance}`,'warn'):''}</div><div class="ops-finance-actions"><button onclick="opsFinanceAction('${esc(j.id)}','cost')">${j.costs?.recordedAt?'Update costs':'Enter actual costs'}</button><button onclick="opsFinanceAction('${esc(j.id)}','estimate')">${j.estimate?'Update estimate':'Create estimate'}</button><button onclick="opsCustomerPortal('${esc(j.id)}',this)">Copy customer portal</button><button onclick="opsFinanceAction('${esc(j.id)}','accept')">Record approval</button><button onclick="opsFinanceAction('${esc(j.id)}','deposit')">Record deposit</button><button onclick="opsFinanceAction('${esc(j.id)}','invoice')">Issue invoice</button><button onclick="opsFinanceAction('${esc(j.id)}','payment')">Record payment</button><button onclick="opsPrintDocument('${esc(j.id)}','estimate')">Print estimate</button><button onclick="opsPrintDocument('${esc(j.id)}','invoice')">Print invoice</button></div></article>`}).join('')}</div>`}
