function openShiftBoard(){const rows=openShiftJobs(),identity=employeeIdentity();if(!rows.length)return empty('No open shifts right now','When a manager opens crew spots on an upcoming job, they will appear here.');return`<div class="ops-open-shifts">${rows.map(j=>{const crew=crewNames(j),needed=Math.max(1,Number(j.crewNeeded||1)),remaining=Math.max(0,needed-crew.length),claimed=identity&&crew.some(x=>x.toLowerCase()===identity.toLowerCase()),claims=Array.isArray(j.shiftClaims)?j.shiftClaims:[],releasable=claimed&&(claims.some(x=>String(x.employee||x).toLowerCase()===identity.toLowerCase())||String(j.lastShiftClaim?.employee||'').toLowerCase()===identity.toLowerCase()),button=claimed?(releasable?`<button class="release" onclick="opsReleaseShift('${esc(j.id)}')">Release shift</button>`:'<button disabled>Assigned</button>'):(remaining&&identity?`<button onclick="opsClaimShift('${esc(j.id)}')">Pick up shift</button>`:`<button disabled>${identity?'Shift full':'Sign in again'}</button>`),serviceHours=scheduledJobMinutes(j)/60,shiftHours=expectedShiftHours(j);return`<article><div class="ops-shift-date"><strong>${dateLabel((j.date||'')+'T12:00:00')}</strong><span>${esc(eventTime(j))}–${esc(j.endTime||'TBD')}</span><div class="ops-shift-hours"><b>${shiftHours.toFixed(1)} hrs expected</b><small>${serviceHours.toFixed(1)} hrs job + 1.5 hrs travel / dump</small></div></div><div class="ops-shift-main"><span>${esc(j.serviceType||'Garage service')}</span><h2>${esc(j.customer||'Customer job')}</h2><p>${esc(j.address||'Location not recorded')}</p><div class="ops-shift-crew"><b>${remaining?`${remaining} spot${remaining===1?'':'s'} remaining`:'Crew full'}</b><span>${crew.length?'Assigned: '+esc(crew.join(', ')):'No crew assigned yet'}</span></div></div><div class="ops-shift-actions">${j.address?`<a href="${routeUrl(j.address)}" target="_blank" rel="noopener">Route</a>`:''}${button}</div></article>`}).join('')}</div>`}
function myShiftBoard(){const rows=myShiftJobs(),identity=employeeIdentity();if(!identity)return empty('Sign in again','Your employee identity is required to build a personal schedule.');if(!rows.length)return empty('No upcoming shifts assigned','Claim an open shift or ask a manager to assign you from the Hub schedule.',`<button class="ops-button primary" onclick="opsGo('open_shifts')">See open shifts</button>`);return`<div class="ops-open-shifts">${rows.map(j=>`<article><div class="ops-shift-date"><strong>${dateLabel((j.date||'')+'T12:00:00')}</strong><span>${esc(eventTime(j))}–${esc(j.endTime||'TBD')}</span></div><div class="ops-shift-main"><span>${esc(jobStage(j).replaceAll('_',' '))}</span><h2>${esc(j.customer||'Customer job')}</h2><p>${esc(j.address||'Location not recorded')}</p><div class="ops-shift-crew"><b>${esc(j.serviceType||'Garage service')}</b><span>Working with ${esc(crewNames(j).filter(n=>!sameEmployee(n,identity)).join(', ')||'your assigned crew')}</span></div></div><div class="ops-shift-actions">${j.address?`<a href="${routeUrl(j.address)}" target="_blank" rel="noopener">Route</a>`:''}<button class="calendar" type="button" onclick="opsDownloadShift('${esc(j.id)}')">Add to calendar</button><a class="primary" href="/crew/prejob.html?jobId=${encodeURIComponent(j.id)}">Open brief</a></div></article>`).join('')}</div>`}
