const claimAvailableShift=window.opsClaimShift;window.opsClaimShift=async id=>{const job=jobs().find(x=>x.id===id),identity=employeeIdentity(),conflict=job&&identity?unavailableFor(job,identity):null;if(conflict){if(typeof showToast==='function')showToast('This shift overlaps time you marked unavailable');return}return claimAvailableShift(id)};

function availabilityBoard(){const identity=employeeIdentity(),rows=activeAvailability().filter(x=>sameEmployee(x.employee,identity)).sort((a,b)=>String(a.date+a.time).localeCompare(String(b.date+b.time))),selected=S.availabilitySelected||day();if(!identity)return empty('Sign in again','Your employee identity is required before time off can be saved.');return`<div class="ops-columns"><section class="ops-card span-7"><div class="ops-card-head"><div><span class="ops-eyebrow">TIME-OFF CALENDAR</span><h2>Tap a day to block it off</h2></div>${badge(rows.length+' block'+(rows.length===1?'':'s'),'info')}</div><p class="ops-body">Blocked time immediately prevents manager assignment and shift pickup conflicts.</p>${availabilityCalendar(identity)}</section><section class="ops-card span-5"><span class="ops-eyebrow">SELECTED DAY</span><h2>${dateLabel(selected+'T12:00:00')}</h2><p class="ops-body">Block the whole day, or switch to a custom time window.</p><form class="ops-availability-form" onsubmit="opsSaveAvailability(event)"><input name="date" type="hidden" value="${esc(selected)}"><label class="ops-all-day"><input name="allDay" type="checkbox" ${S.availabilityAllDay?'checked':''} onchange="opsAvailabilityAllDay(this.checked)"><span><b>Block the full day</b><small>Turn this off for an appointment or partial day.</small></span></label><div class="ops-time-window ${S.availabilityAllDay?'ops-hidden':''}"><label><span>Start</span><input name="time" type="time" value="08:00"></label><label><span>End</span><input name="endTime" type="time" value="17:00"></label></div><label><span>Reason</span><input name="reason" maxlength="100" placeholder="Time off, school, appointment…"></label><button class="ops-button primary">Block this time</button><small id="ops-availability-status">Visible only to you and EGC managers.</small></form></section><section class="ops-card span-12"><div class="ops-card-head"><div><span class="ops-eyebrow">UPCOMING</span><h2>My blocked time</h2></div></div>${rows.length?`<div class="ops-availability-list">${rows.map(x=>`<article><div><strong>${dateLabel((x.date||'')+'T12:00:00')}</strong><span>${x.allDay?'All day':`${esc(eventTime(x))}–${esc(x.endTime||'')}`}</span></div><p>${esc(x.reason||'Unavailable')}</p><button onclick="opsRemoveAvailability('${esc(x.id)}')">Remove</button></article>`).join('')}</div>`:empty('No time off blocked','Tap a day on the calendar to protect it before the work schedule is built.')}</section></div>`}
window.opsAvailabilityMove=n=>{const month=availabilityMonth();month.setMonth(month.getMonth()+Number(n));S.availabilityAnchor=isoDate(month);render()};
window.opsAvailabilityToday=()=>{S.availabilityAnchor=day().slice(0,7)+'-01';S.availabilitySelected=day();render()};
