window.opsSaveAvailability=async event=>{event.preventDefault();const identity=employeeIdentity(),form=event.currentTarget,status=$('#ops-availability-status'),fd=new FormData(form),date=String(fd.get('date')||''),allDay=fd.has('allDay'),time=allDay?'00:00':String(fd.get('time')||''),endTime=allDay?'23:59':String(fd.get('endTime')||''),reason=String(fd.get('reason')||'Unavailable').trim()||'Unavailable';if(!identity||!date||date<day()||!overlaps(minutes(time),minutes(endTime),minutes(time),minutes(endTime))){if(status)status.textContent='Choose a future calendar day and a valid time window.';return}const assigned=jobs().find(j=>activeScheduleJob(j)&&String(j.date||'')===date&&crewNames(j).some(n=>sameEmployee(n,identity))&&overlaps(minutes(time),minutes(endTime),minutes(j.time),minutes(j.endTime)));if(assigned){if(status)status.textContent=`You are already assigned to ${assigned.customer||assigned.serviceType||'a job'} during this time. Release the shift or ask a manager to reassign it first.`;return}const id=`availability-${personKey(identity)}-${Date.now().toString(36)}`,now=new Date().toISOString(),record={id,type:'availability',recordType:'crew_availability',employee:identity,date,time,endTime,allDay,reason,status:'active',createdAt:now,updatedAt:now};try{await db.collection('jobs').doc(id).set(record,{merge:true});if(typeof jobsCache!=='undefined')jobsCache=[...jobsCache.filter(x=>x.id!==id),record];render();if(typeof showToast==='function')showToast(allDay?'Day blocked off':'Unavailable time saved')}catch(e){if(status)status.textContent='The Hub could not save this time. Check the connection and retry.'}};
window.opsRemoveAvailability=async id=>{const identity=employeeIdentity(),row=availabilityRows().find(x=>x.id===id);if(!row||!sameEmployee(row.employee,identity))return;const now=new Date().toISOString();try{await db.collection('jobs').doc(id).set({status:'cancelled',cancelledAt:now,updatedAt:now},{merge:true});if(typeof jobsCache!=='undefined')jobsCache=jobsCache.map(x=>x.id===id?{...x,status:'cancelled',cancelledAt:now,updatedAt:now}:x);render();if(typeof showToast==='function')showToast('Unavailable time removed')}catch(e){if(typeof showToast==='function')showToast('Could not remove this block')}};

function timesheetRange(){const start=weekStart(S.timesheetAnchor);start.setHours(12,0,0,0);const end=new Date(start);end.setDate(start.getDate()+6);return{start,end,startDate:isoDate(start),endDate:isoDate(end)}}
function timesheetRows(){const range=timesheetRange(),individual=S.people.timeEntries.filter(e=>{const date=String(e.clockInAt||'').slice(0,10);return date>=range.startDate&&date<=range.endDate});if(individual.length)return individual.map(e=>({id:e.id,employee:e.employeeName||e.employee,date:String(e.clockInAt||'').slice(0,10),customer:e.jobLabel||'General company time',service:e.payType||'hourly',jobId:e.jobId||'',hours:entryHours(e),startAt:e.clockInAt||'',completedAt:e.clockOutAt||'',approvalStatus:e.approvalStatus||e.status,hourlyRate:Number(e.hourlyRate||0),gross:entryGross(e)})).sort((a,b)=>String(a.employee+a.date).localeCompare(String(b.employee+b.date)));const rows=[];jobs().filter(j=>j.type!=='walkthrough'&&j.type!=='blocked'&&String(j.date||'')>=range.startDate&&String(j.date||'')<=range.endDate&&Number(j.timeTracking?.elapsedHours||j.hoursOnSite||0)>0).forEach(j=>{const hours=Number(j.timeTracking?.elapsedHours||j.hoursOnSite||0),crew=crewNames(j),fallback=j.timeTracking?.recordedBy?[j.timeTracking.recordedBy]:[];(crew.length?crew:fallback).forEach(employee=>rows.push({employee,date:j.date,customer:j.customer||'Customer',service:j.serviceType||'Garage service',jobId:j.id,hours,startAt:j.timeTracking?.startedAt||j.startedAt||'',completedAt:j.timeTracking?.completedAt||j.completedAt||'',approvalStatus:'legacy'}))});return rows.sort((a,b)=>String(a.employee+a.date).localeCompare(String(b.employee+b.date)))}
function approvedGustoRows(){const range=timesheetRange();return S.people.timeEntries.filter(entry=>{const date=String(entry.clockInAt||'').slice(0,10);return entry.approvalStatus==='approved'&&Boolean(entry.clockOutAt)&&date>=range.startDate&&date<=range.endDate}).map(entry=>({employee:entry.employeeName||entry.employee,username:entry.employee||'',date:String(entry.clockInAt||'').slice(0,10),workweek:`${range.startDate} to ${range.endDate}`,startedAt:entry.clockInAt||'',endedAt:entry.clockOutAt||'',hours:entryHours(entry),job:entry.jobLabel||'General company time',memo:entry.jobId?`EGC Hub job ${entry.jobId}`:'EGC Employee Hub'})).sort((a,b)=>String(a.employee+a.startedAt).localeCompare(String(b.employee+b.startedAt)))}
function timesheetBoard(){const range=timesheetRange(),rows=timesheetRows(),gusto=approvedGustoRows(),groups={};rows.forEach(r=>(groups[r.employee]||=[]).push(r));const total=rows.reduce((n,r)=>n+r.hours,0);return`<div class="ops-schedule-bar"><div><button onclick="opsTimesheetMove(-1)" aria-label="Previous week">←</button><button onclick="opsTimesheetMove(1)" aria-label="Next week">→</button><strong>${range.start.toLocaleDateString('en-US',{month:'short',day:'numeric'})} – ${range.end.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</strong></div><div>${badge(total.toFixed(2)+' crew hours','info')}<button class="ops-button" ${rows.length?'':'disabled'} onclick="opsDownloadTimesheets()">Download CSV</button><button class="ops-button primary" ${gusto.length?'':'disabled'} onclick="opsDownloadGusto()">Download for Gusto</button></div></div><div class="ops-boundary"><strong>Individual timecards</strong><span>Each employee clocks their own time, breaks, and optional on-shift location.</span><span>The Gusto file includes approved, completed timecards only—one row per shift for Smart Import review.</span></div>${Object.keys(groups).length?`<div class="ops-timesheets">${Object.entries(groups).map(([employee,items])=>`<section><header><div><span>EMPLOYEE</span><h2>${esc(employee)}</h2></div><strong>${items.reduce((n,x)=>n+x.hours,0).toFixed(2)} hrs · ${money(items.reduce((n,x)=>n+Number(x.gross||0),0))}</strong></header><div>${items.map(x=>`<article class="ops-time-row"><time>${dateLabel((x.date||'')+'T12:00:00')}</time><div><b>${esc(x.customer)}</b><span>${esc(x.service)} ${x.jobId?'· '+esc(x.jobId):''}</span></div><strong>${x.hours.toFixed(2)}</strong><div>${badge(x.approvalStatus||'open',x.approvalStatus==='approved'?'good':x.approvalStatus==='rejected'?'warn':'info')}${x.id&&x.approvalStatus==='pending'?`<button onclick="opsApproveTime('${esc(x.id)}','approved')">Approve</button><button onclick="opsApproveTime('${esc(x.id)}','rejected')">Reject</button>`:''}</div></article>`).join('')}</div></section>`).join('')}</div>`:empty('No timecards this week','Employees clock in from My day. Submitted time appears here for approval.')}`}
window.opsTimesheetMove=n=>{const d=weekStart(S.timesheetAnchor);d.setDate(d.getDate()+Number(n)*7);S.timesheetAnchor=isoDate(d);render()};window.opsTimesheetToday=()=>{S.timesheetAnchor='';render()};
const csvCell=value=>{let text=String(value??'');if(/^[=+\-@]/.test(text))text="'"+text;return`"${text.replaceAll('"','""')}"`};
window.opsDownloadCustomers=()=>{const rows=customerRows();if(!rows.length)return;const data=[['Customer','Phone','Email','Address','HighLevel contact ID','Visits','Sold work','Recorded paid','Last activity'],...rows.map(c=>[c.name,c.phone,c.email,c.address,c.highlevelContactId,c.jobs.length,c.value.toFixed(2),c.paid.toFixed(2),[...c.jobs].map(j=>j.date||'').sort().at(-1)||''])],csv=data.map(row=>row.map(csvCell).join(',')).join('\r\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`egc-customers-${day()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
